// Как выгружает «Get cookies.txt LOCALLY»: заголовок, #HttpOnly_, куки
// других сайтов.
const sampleCookies = "# Netscape HTTP Cookie File\n" +
	"# This file is generated by Get cookies.txt LOCALLY. Edit at your own risk.\n" +
	"\n" +
	".youtube.com\tTRUE\t/\tTRUE\t1830000000\tSAPISID\tyt-secret-1\n" +
	"#HttpOnly_.youtube.com\tTRUE\t/\tTRUE\t1820000000\t__Secure-3PSID\tyt-secret-2\n" +
	".youtube.com\tTRUE\t/\tFALSE\t0\tPREF\tf6=40000000\n" +
	".google.com\tTRUE\t/\tTRUE\t1830000000\tSID\tgoogle-secret\n"

func setCookiesForTest(t *testing.T) string {
	t.Helper()
	path := filepath.Join(t.TempDir(), "youtube-cookies.txt")
	SetCookiesFile(path)
	t.Cleanup(func() { SetCookiesFile("") })
	return path
}

func TestParseCookies_KeepsOnlyYouTube(t *testing.T) {
	for name, in := range map[string]string{
		"as exported":  sampleCookies,
		"windows, bom": "\xef\xbb\xbf" + strings.ReplaceAll(sampleCookies, "\n", "\r\n"),
	} {
		out, info, err := parseCookies([]byte(in))
		if err != nil {
			t.Fatalf("%s: %v", name, err)
		}
		if info.Count != 3 || !info.SignedIn || info.Expires == nil || info.Expires.Unix() != 1820000000 {
			t.Errorf("%s: info %+v", name, info)
		}
		s := string(out)
		if !strings.HasPrefix(s, "# Netscape HTTP Cookie File\n") || strings.Contains(s, "google") ||
			!strings.Contains(s, "#HttpOnly_.youtube.com") || strings.Count(s, "youtube.com") != 3 {
			t.Errorf("%s: kept %q", name, s)
		}
	}

	if _, info, err := parseCookies([]byte(".youtube.com\tTRUE\t/\tFALSE\t\tPREF\tx\n")); err != nil || info.SignedIn || info.Count != 1 {
		t.Errorf("without a sign-in: %+v, %v", info, err)
	}
	for in, want := range map[string]error{
		`[{"domain": ".youtube.com", "name": "SID"}]`: ErrCookiesJSON,
		"hello\nworld\n": ErrCookiesFormat,
		".google.com\tTRUE\t/\tTRUE\t0\tSID\tsecret\n": ErrNoYouTubeCookies,
	} {
		if _, _, err := parseCookies([]byte(in)); !errors.Is(err, want) {
			t.Errorf("%q: %v, want %v", in, err, want)
		}
	}
}

// Каждый запуск yt-dlp — со своей копией кук, после него она удаляется, а
// файл админа не меняется.
func TestCookies_EveryRunGetsItsOwnCopy(t *testing.T) {
	path := setCookiesForTest(t)
	if _, ok := Cookies(); ok {
		t.Fatal("cookies before any upload")
	}
	if _, err := SaveCookies([]byte("garbage")); !errors.Is(err, ErrCookiesFormat) {
		t.Fatalf("garbage: %v", err)
	}
	if _, err := os.Stat(path); !os.IsNotExist(err) {
		t.Fatalf("garbage was saved: %v", err)
	}
	info, err := SaveCookies([]byte(sampleCookies))
	if err != nil || info.Count != 3 {
		t.Fatalf("SaveCookies: %+v, %v", info, err)
	}
	st, err := os.Stat(path)
	if err != nil || st.Mode().Perm() != 0o600 {
		t.Fatalf("cookies file: %v, %v", st, err)
	}
	saved, _ := os.ReadFile(path)
	if got, ok := Cookies(); !ok || got.Count != 3 || got.UpdatedAt.IsZero() {
		t.Fatalf("Cookies: %+v, %v", got, ok)
	}

	calls := fakeYtDlp(t, "")
	if _, err := Download(context.Background(), "okA", t.TempDir(), "x"); err != nil {
		t.Fatalf("Download with cookies: %v", err) // фейк падает, если копии нет
	}
	args := strings.Fields((*calls)[0])
	i := slices.Index(args, "--cookies")
	if i < 0 || args[i+1] == path {
		t.Fatalf("yt-dlp args %q: want a copy of the cookies", args)
	}
	if _, err := os.Stat(args[i+1]); !os.IsNotExist(err) {
		t.Errorf("the copy %s is still there: %v", args[i+1], err)
	}
	if now, _ := os.ReadFile(path); !bytes.Equal(now, saved) {
		t.Error("the run changed the admin's file")
	}

	if err := RemoveCookies(); err != nil {
		t.Fatal(err)
	}
	if _, ok := Cookies(); ok {
		t.Fatal("cookies after removing them")
	}
	Download(context.Background(), "okA", t.TempDir(), "x")
	if strings.Contains((*calls)[1], "--cookies") {
		t.Errorf("removed cookies still passed: %q", (*calls)[1])
	}
}

// Помощник берёт куки при запуске; загрузили или удалили — следующий
// запрос идёт уже через новый.
func TestWarm_RestartsWhenCookiesChange(t *testing.T) {
	calls := fakeYtDlp(t, "")
	setCookiesForTest(t)
	enableWarmForTest(t)
	resolve := func() string {
		t.Helper()
		m, err := Resolve(context.Background(), "okA")
		if err != nil {
			t.Fatalf("Resolve: %v", err)
		}
		return m.URL
	}
	if u := resolve(); strings.HasSuffix(u, "?cookies=1") {
		t.Fatalf("cookies before upload: %s", u)
	}
	if _, err := SaveCookies([]byte(sampleCookies)); err != nil {
		t.Fatal(err)
	}
	if u := resolve(); !strings.HasSuffix(u, "?cookies=1") {
		t.Fatalf("the helper didn't take the new cookies: %s", u)
	}
	resolve()
	if n := countCalls(*calls, "-c "); n != 2 {
		t.Fatalf("helpers started: %d, want 2", n)
	}
	RemoveCookies()
	if u := resolve(); strings.HasSuffix(u, "?cookies=1") {
		t.Fatalf("cookies after removing them: %s", u)
	}
}
